18	// cursorImporter imports Cursor transcripts. Cursor uses the same JSONL line
19	// format as Claude Code (role-tagged), so it reuses the shared user-prompt
20	// detection and content extraction. Cursor records neither model nor token
21	// usage, so imported turns carry an empty model and nil tokens.
22	type cursorImporter struct{}
23	
24	func (cursorImporter) Name() string { return string(agent.AgentNameCursor) }
25	
26	func (cursorImporter) AgentType() types.AgentType { return agent.AgentTypeCursor }
27	
28	// Discover returns Cursor transcript files for the repo modified within the
29	// lookback window. Cursor stores sessions either flat (<dir>/<id>.jsonl) or
30	// nested (<dir>/<id>/<id>.jsonl, the IDE layout); both are discovered.
31	func (cursorImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
32		dir := overridePath
33		if dir == "" {
34			ag := &cursor.CursorAgent{}
35			d, err := ag.GetSessionDir(repoRoot)
36			if err != nil {
37				return nil, fmt.Errorf("resolve cursor session dir: %w", err)
38			}
39			dir = d
40		}
41		entries, err := os.ReadDir(dir)
42		if err != nil {
43			if os.IsNotExist(err) {
44				return nil, nil
45			}
46			return nil, fmt.Errorf("read cursor session dir: %w", err)
47		}
48		cutoff := now.AddDate(0, 0, -LookbackDays)
49		var out []SessionFile
50		for _, e := range entries {
51			stem, path := cursorSessionFile(dir, e)
52			if path == "" {
53				continue
54			}
55			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, stem) {
56				continue
57			}
58			info, statErr := os.Stat(path)
59			if statErr != nil || info.ModTime().Before(cutoff) {
60				continue
61			}
62			out = append(out, SessionFile{Path: path, SessionID: stem})
63		}
64		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
65		return out, nil
66	}
