68	// cursorSessionFile maps a directory entry to a (sessionID, transcript path),
69	// resolving both the flat and nested Cursor layouts. Returns an empty path for
70	// entries that are not Cursor transcripts.
71	func cursorSessionFile(dir string, e os.DirEntry) (sessionID, path string) {
72		if e.IsDir() {
73			nested := filepath.Join(dir, e.Name(), e.Name()+".jsonl")
74			if _, err := os.Stat(nested); err == nil {
75				return e.Name(), nested
76			}
77			return "", ""
78		}
79		if !strings.HasSuffix(e.Name(), ".jsonl") {
80			return "", ""
81		}
82		return strings.TrimSuffix(e.Name(), ".jsonl"), filepath.Join(dir, e.Name())
83	}
