18	// piImporter imports Pi transcripts (~/.pi/agent/sessions/<repo>/<ts>_<uuid>.jsonl).
19	// Pi records token usage and the model on every assistant message, so imported
20	// turns carry both via the agent's own CalculateTokenUsage / ExtractModel.
21	type piImporter struct{}
22	
23	func (piImporter) Name() string { return string(agent.AgentNamePi) }
24	
25	func (piImporter) AgentType() types.AgentType { return agent.AgentTypePi }
26	
27	// Discover returns Pi transcript files for the repo modified within the lookback
28	// window. The session ID is the <uuid> suffix of the <timestamp>_<uuid> file
29	// stem (Pi timestamps use dashes, so the first underscore is the separator).
30	func (piImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
31		dir := overridePath
32		if dir == "" {
33			ag := &pi.PiAgent{}
34			d, err := ag.GetSessionDir(repoRoot)
35			if err != nil {
36				return nil, fmt.Errorf("resolve pi session dir: %w", err)
37			}
38			dir = d
39		}
40		entries, err := os.ReadDir(dir)
41		if err != nil {
42			if os.IsNotExist(err) {
43				return nil, nil
44			}
45			return nil, fmt.Errorf("read pi session dir: %w", err)
46		}
47		cutoff := now.AddDate(0, 0, -LookbackDays)
48		var out []SessionFile
49		for _, e := range entries {
50			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
51				continue
52			}
53			stem := strings.TrimSuffix(e.Name(), ".jsonl")
54			sessionID := piSessionID(stem)
55			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, sessionID) {
56				continue
57			}
58			info, statErr := e.Info()
59			if statErr != nil || info.ModTime().Before(cutoff) {
60				continue
61			}
62			out = append(out, SessionFile{Path: filepath.Join(dir, e.Name()), SessionID: sessionID})
63		}
64		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
65		return out, nil
66	}
