68	// piSessionID extracts the <uuid> portion of a "<timestamp>_<uuid>" file stem.
69	// Falls back to the whole stem when there is no underscore separator.
70	func piSessionID(stem string) string {
71		if i := strings.Index(stem, "_"); i >= 0 {
72			return stem[i+1:]
73		}
74		return stem
75	}
76	
77	// SplitTurns produces one Turn per user-prompt message line, bounded by the
78	// next. Token usage and model are delegated to the Pi agent so import reuses the
79	// same accounting (branch-aware) the live path uses.
80	func (piImporter) SplitTurns(_ SessionFile, full []byte) ([]Turn, error) {
81		rawLines := splitRawLines(full)
82		var starts []int
83		for i, raw := range rawLines {
84			if _, ok := piPromptText(raw); ok {
85				starts = append(starts, i)
86			}
87		}
88	
89		ag := &pi.PiAgent{}
90		turns := make([]Turn, 0, len(starts))
91		for k, start := range starts {
92			end := len(rawLines)
93			if k+1 < len(starts) {
94				end = starts[k+1]
95			}
96	
97			// Bound token usage to [start, end): truncate to the first `end` lines,
98			// then let the agent helper slice from `start`.
99			truncated := joinLines(rawLines[:end])
100			tokens, err := ag.CalculateTokenUsage(truncated, start)
101			if err != nil {
102				return nil, fmt.Errorf("token usage for turn %d: %w", k, err)
103			}
104			model, mErr := ag.ExtractModel(joinLines(rawLines[start:end]))
105			if mErr != nil {
106				model = ""
107			}
108	
109			var entry pijsonl.Entry
110			if err := json.Unmarshal(rawLines[start], &entry); err != nil {
111				continue
112			}
113			ts, parseErr := time.Parse(time.RFC3339, entry.Timestamp)
114			if parseErr != nil {
115				ts = time.Time{}
116			}
117			prompt, _ := piPromptText(rawLines[start])
118	
119			turns = append(turns, Turn{
120				LineStart: start,
121				LineEnd:   end,
122				UUID:      entry.ID,
123				Prompt:    prompt,
124				Model:     model,
125				CreatedAt: ts,
126				Tokens:    tokens,
127			})
128		}
129		return turns, nil
130	}
131	
132	// piPromptText reports whether a raw Pi JSONL line is a user-prompt message and
133	// returns its text. Pi user content may be a plain string or an array of typed
134	// blocks; toolResult/assistant messages and empty content return false.
135	func piPromptText(raw []byte) (string, bool) {
136		var entry pijsonl.Entry
137		if err := json.Unmarshal(raw, &entry); err != nil {
138			return "", false
139		}
140		if entry.Type != pijsonl.EntryTypeMessage || entry.Message.Role != pijsonl.RoleUser {
141			return "", false
142		}
143		if s := pijsonl.DecodeStringContent(entry.Message.Content); s != "" {
144			return s, true
145		}
146		var items []pijsonl.ContentItem
147		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
148			return "", false
149		}
150		var texts []string
151		for _, it := range items {
152			if it.Type == pijsonl.ContentTypeText && it.Text != "" {
153				texts = append(texts, it.Text)
154			}
155		}
156		if len(texts) == 0 {
157			return "", false
158		}
159		return strings.Join(texts, "\n\n"), true
160	}
