115	// factoryPromptText reports whether a raw Droid JSONL line is a user-prompt
116	// message and returns its text. Droid tags the role inside the inner message;
117	// tool_result user messages carry no extractable text and return false.
118	func factoryPromptText(raw []byte) (string, bool) {
119		var env struct {
120			Type    string          `json:"type"`
121			Message json.RawMessage `json:"message"`
122		}
