37	// Discover walks the Codex sessions tree and returns transcripts belonging to
38	// this repo (by session_meta cwd) modified within the lookback window.
39	func (codexImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
40		dir := overridePath
41		if dir == "" {
42			ag := &codex.CodexAgent{}
43			d, err := ag.GetSessionDir(repoRoot)
44			if err != nil {
45				return nil, fmt.Errorf("resolve codex session dir: %w", err)
46			}
47			dir = d
48		}
49		cutoff := now.AddDate(0, 0, -LookbackDays)
50		var out []SessionFile
51		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
52			if err != nil {
53				if os.IsNotExist(err) {
54					return nil // missing root or vanished entry: nothing to import
55				}
56				return err
57			}
58			if d.IsDir() || !strings.HasSuffix(d.Name(), ".jsonl") {
59				return nil
60			}
61			info, statErr := d.Info()
62			if statErr != nil || info.ModTime().Before(cutoff) {
63				return nil //nolint:nilerr // skip unreadable/old entries, keep walking
64			}
65			meta, metaErr := codexReadSessionMeta(path)
66			if metaErr != nil || !repoMatches(meta.Cwd, repoRoot) {
67				return nil //nolint:nilerr // skip sessions we can't attribute to this repo
68			}
69			sessionID := meta.ID
70			if sessionID == "" {
71				sessionID = strings.TrimSuffix(d.Name(), ".jsonl")
72			}
73			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, sessionID) {
74				return nil
75			}
76			out = append(out, SessionFile{Path: path, SessionID: sessionID})
77			return nil
78		})
79		if walkErr != nil {
80			return nil, fmt.Errorf("walk codex sessions: %w", walkErr)
81		}
82		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
83		return out, nil
84	}
