86	// codexReadSessionMeta reads the first JSONL line of a rollout file and returns
87	// its session_meta payload. The first line must be session_meta by Codex's
88	// format.
89	func codexReadSessionMeta(path string) (codexSessionMeta, error) {
90		f, err := os.Open(path) //nolint:gosec // path discovered by walking the configured session dir
91		if err != nil {
92			return codexSessionMeta{}, fmt.Errorf("open rollout: %w", err)
93		}
94		defer func() { _ = f.Close() }()
95		r := bufio.NewReader(f)
96		first, err := r.ReadBytes('\n')
97		if len(first) == 0 && err != nil {
98			return codexSessionMeta{}, fmt.Errorf("read session_meta line: %w", err)
99		}
100		var line struct {
101			Type    string           `json:"type"`
102			Payload codexSessionMeta `json:"payload"`
103		}
104		if jsonErr := json.Unmarshal(first, &line); jsonErr != nil || line.Type != "session_meta" {
105			return codexSessionMeta{}, errors.New("first line is not session_meta")
106		}
107		return line.Payload, nil
108	}
