191	// codexLineTime returns the RFC3339 timestamp on a rollout line, or the zero
192	// time when absent or unparseable.
193	func codexLineTime(raw []byte) time.Time {
194		var line struct {
195			Timestamp string `json:"timestamp"`
196		}
197		if err := json.Unmarshal(raw, &line); err != nil {
198			return time.Time{}
199		}
200		ts, err := time.Parse(time.RFC3339, line.Timestamp)
201		if err != nil {
202			return time.Time{}
203		}
204		return ts
205	}
