207	// repoMatches reports whether cwd is the repo root or a descendant of it. Both
208	// paths are normalized (cleaned, symlinks resolved best-effort) before
209	// comparison. Used by the global/flat-store importers (Codex, Copilot) to keep
210	// only sessions belonging to this repo.
211	func repoMatches(cwd, repoRoot string) bool {
212		if cwd == "" || repoRoot == "" {
213			return false
214		}
215		rel, err := filepath.Rel(normalizePath(repoRoot), normalizePath(cwd))
216		if err != nil {
217			return false
218		}
219		return !strings.HasPrefix(rel, "..")
220	}
221	
222	// normalizePath cleans a path and resolves symlinks when possible, so a cwd
223	// recorded through a symlinked path (e.g. macOS /var → /private/var) still
224	// matches the repo root. Falls back to the cleaned path when the target does
225	// not exist on this machine.
226	func normalizePath(p string) string {
227		cleaned := filepath.Clean(p)
228		if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
229			return resolved
230		}
231		return cleaned
232	}
